  ('liliw-laguna', 'BPLO', 'Occupational / Work Permit', 'Official Mayor''s permit for individuals practicing a trade or employed within the municipality.', '["One (1) Valid Government ID","Food Handler / Worker Health Card (Health Office)","Police Clearance or NBI Clearance","Community Tax Certificate (Cedula)"]'::jsonb, '₱100.00 – ₱200.00 — pay at Municipal Treasurer', '1-2 working days', 3),

