  ('liliw-laguna', 'Civil Registrar', 'Certificate of Live Birth (Timely Registration)', 'Registration of newborn birth within 30 days of delivery.', '["Duly accomplished COLB Form 102 signed by attending physician/midwife","Valid IDs of parents","Marriage Certificate of parents (if married)","6 copies Notarized AUSF & AAP (if parents unmarried)"]'::jsonb, 'Free / No charge for basic timely registration', '1-2 working days', 4),
