  ('liliw-laguna', 'Civil Registrar', 'Certified True Copy of Civil Registry Document', 'Official certified true copy or extract of Birth, Marriage, or Death certificate on file in the local registry.', '["One (1) Valid Government ID of requester","Accomplished Request Slip (Book/Page/Registry No.)","Notarized Authorization Letter / SPA (if representative)"]'::jsonb, '₱100.00 per copy — pay at Civil Registrar / Treasurer', '1-2 working days', 6),
  ('liliw-laguna', 'Civil Registrar', 'Marriage License Application', 'Application for marriage license required prior to solemnization of marriage.', '["PSA Birth Certificates of both parties","PSA CENOMAR valid within 6 months","Certificate of Pre-Marriage Counseling (PMOC) from CSWDO & Health Office","Community Tax Certificate (Cedula) of both parties","Valid IDs of both parties","Parental Consent (18-20) / Advice (21-24) if applicable"]'::jsonb, '₱200.00 – ₱300.00 — pay at Municipal Treasurer', '10-12 working days (10-day posting period)', 7),
