  ('liliw-laguna', 'Civil Registrar', 'Legitimation of Child (R.A. 9858)', 'Legal process legitimizing children born out of wedlock upon subsequent marriage of biological parents.', '["Child''s Certified Certificate of Live Birth (Local & PSA)","Parents'' Certified Marriage Contract (Local & PSA)","Joint Notarized Affidavit of Legitimation","PSA CENOMAR of both parents","Valid IDs of both parents"]'::jsonb, '₱250.00 — pay at Municipal Treasurer', '3-5 working days', 9),
